draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 75);
  ctx.lineTo(W/2 - 25, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 75);
  ctx.lineTo(W/2 + 25, H/2 + 50);
  ctx.stroke();

  // human
  ctx.beginPath();
  ctx.arc(W/2 + 150, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 150, H/2 + 50);
  ctx.lineTo(W/2 + 150, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 150, H/2 + 75);
  ctx.lineTo(W/2 + 125, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 150, H/2 + 75);
  ctx.lineTo(W/2 + 175, H/2 + 50);
  ctx.stroke();

  // sadness
  ctx.beginPath();
  ctx.arc(W/2 + 150, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 150, H/2 - 30);
  ctx.lineTo(W/2 + 170, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 150, H/2 - 30);
  ctx.lineTo(W/2 + 130, H/2 - 20);
  ctx.stroke();

  // dog sensing sadness
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 75);
  ctx.lineTo(W/2 + 150, H/2 - 50);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'gray';
  ctx.stroke();
  ctx.lineWidth = 3;

  // head movement
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.arc(0, 0, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
